// lib/hq/figure.js
function TeamFigure2({ team, turns, W = 440, H = 236 }) {
  const t = team || {};
  const crew = t.crew || [];
  const pos = { human: [W / 2, 30] };
  const n = crew.length;
  crew.forEach((m, i) => {
    pos[m.name] = [n === 1 ? W / 2 : 46 + i * (W - 92) / (n - 1), 124];
  });
  const seen = new Set;
  const edges = [];
  for (const [a, b] of turns || []) {
    if (!pos[a] || !pos[b])
      continue;
    const k = [a, b].sort().join("|");
    if (seen.has(k))
      continue;
    seen.add(k);
    const [x1, y1] = pos[a], [x2, y2] = pos[b];
    if (y1 === y2) {
      const mx = (x1 + x2) / 2, my = y1 + 58 + Math.abs(x2 - x1) * 0.1;
      edges.push(html`<path class="hq-e" d=${`M${x1} ${y1} Q${mx} ${my} ${x2} ${y2}`} />`);
    } else {
      edges.push(html`<line class="hq-e" x1=${x1} y1=${y1} x2=${x2} y2=${y2} />`);
    }
  }
  const calls = [];
  for (const m of crew) {
    if (m.state !== "blocked" && m.state !== "handed")
      continue;
    const [x, y] = pos[m.name];
    calls.push(html`<line class="hq-call" x1=${x} y1=${y - 14} x2=${W / 2} y2="44" />`);
  }
  const nodes = [];
  nodes.push(html`<g class="hq-n human"><rect x=${W / 2 - 26} y="16" width="52" height="28" rx="6" /><text x=${W / 2} y="35">人間</text></g>`);
  for (const m of crew) {
    const [x, y] = pos[m.name];
    nodes.push(html`<g class=${"hq-n " + m.state}><circle class="ring" cx=${x} cy=${y} r="15" /><circle class="dot" cx=${x} cy=${y} r="11" />${m.state === "blocked" ? html`<text class="bang" x=${x} y=${y + 4}>!</text>` : ""}<text class="lbl" x=${x} y=${y + 30}>${m.name}</text></g>`);
  }
  const byMember = {};
  const free = [];
  for (const w of t.workers || []) {
    if (!pos[w.from]) {
      free.push(w);
      continue;
    }
    (byMember[w.from] || (byMember[w.from] = [])).push(w);
  }
  for (const [from, ws] of Object.entries(byMember)) {
    const [x] = pos[from];
    ws.forEach((w, i) => {
      const wx = x + (i - (ws.length - 1) / 2) * 34, wy = 204;
      nodes.push(html`<line class="hq-e wk" x1=${x} y1="139" x2=${wx} y2=${wy - 7} /><g class=${"hq-n wkr " + w.state}><circle class="dot" cx=${wx} cy=${wy} r="6" /><text class="lbl s" x=${wx} y=${wy + 20}>${w.name}</text></g>`);
    });
  }
  free.forEach((w, i) => {
    const wx = free.length === 1 ? W / 2 : 30 + i * (W - 60) / (free.length - 1), wy = 204;
    nodes.push(html`<g class=${"hq-n wkr " + w.state}><circle class="dot" cx=${wx} cy=${wy} r="6" /><text class="lbl s" x=${wx} y=${wy + 20}>${w.name}</text></g>`);
  });
  return html`<svg class="hq-svg" viewBox=${`0 0 ${W} ${H}`} role="img" aria-label=${`${t.name} のメンバーとターン`}>${edges}${calls}${nodes}</svg>`;
}

